/* Player-facing introduction, contextual help, and a real first-task walkthrough. */
'use strict';
function guideState(){if(!state.gameGuide||state.gameGuide.v!==1)state.gameGuide={v:1,welcome:false,studySeen:[],awaySeen:[],walk:null};const g=state.gameGuide;for(const key of ['studySeen','awaySeen'])if(!Array.isArray(g[key]))g[key]=[];return g;}
function finishWelcome(){guideState().welcome=true;save();}
function guideActions(){return `<div class="actions"><button id="guideChoose">我想自己选章节</button><button id="guideStudy" class="primary">带我玩一次学习章</button><button id="guideBeach">先去海边冒险</button></div>`;}
function showGameGuide(first=false,page='overview'){const pages={overview:{title:first?'欢迎来到拾知小镇':'拾知小镇 · 旅行指南',intro:'这是一款边探索、边整理知识的小游戏。前四章可以学习课程，海边和圣诞两章则是独立的轻冒险。顶部“导入知识库”可上传整套资料或粘贴笔记。原来的失落档案、星叶群岛和林间寻物，可从“其他冒险”进入。',steps:[['先选一章','点“六章地图”选择目的地。六章都能直接进入，可随时切换，进度分别保存。'],['看到什么就点一点','点击场景物件探索知识，操作里面的小机关后收进背包；再拖到对应装置，或先选中背包物件、再点目的地。'],['看当前任务，不必猜','左上角显示当前学习目标；海边和圣诞顶部显示三步任务，底部显示下一步提示。'],['迷路随时回来','顶部“玩法指南”可重开说明。学习章的罗盘能定位素材，知识素材箱可以随时重读。']]},study:{title:'学习章：先读懂，再动手',intro:'每一章从自己的第一节开始。只锁定本章内的小节顺序，不要求先通过其他章节。',steps:[['① 找到并阅读','点击散落的齿轮、种子、镜片、信件和地图，阅读定义与示例后收集；有些装置需要先到场景里找到部件，再组装。'],['② 放进本节装置','收下后可直接点本节装置放入，也可拖入；装置显示已整理/总数。点开还能定位未读内容。'],['③ 完成小节并交付','整理齐本节后，按装置提示完成操作与判断：术语配对、预算分配、收益核算、权限设置等，再收好成果刷新下一节。全章基础收齐，到“知识素材箱”交付后，练习才会激活。'],['④ 练习、复习、修错','练习中可回素材箱查知识。错题独立答对后修复；本章完整测验达到90%就算通关。']]},seaside:{title:'海边章：寄出一封夏日来信',intro:'本章没有课程题目。完成三项小机关，让海风铃和归航灯重新工作。',steps:[['① 修复海风铃','点击三枚碎片收进小包，再拖到海风铃架；也能先选背包碎片、再点风铃架。'],['② 点亮归航路','点击航标可以转向，按照码头旁的路线线索调整，最后点“试亮航灯”。'],['③ 寄出夏日来信','读明信片上的暗号，依次选三个符号后投递。选错可以重新排列，物件不会因此丢失。'],['随时暂停','切换章节或刷新后仍保留任务进度。顶部“六章地图”可去其他章节。']]},winter:{title:'圣诞章：把暖意送进雪夜',intro:'本章没有课程题目。投递礼物、点亮街灯，再为小镇奏响钟声。',steps:[['① 按缎带送礼','收集礼物，按收件处标注的缎带颜色送达。可拖放，也可先选礼物、再点击收件处。'],['② 操作联动街灯','每个开关会同时翻转几盏灯；按钮下写着连接关系。让三盏灯都亮起，再确认。'],['③ 奏响钟声','读乐谱暗号，依次敲三个符号后提交。需要时可以重新排列。'],['不必一口气玩完','本章任务顺序固定，但可随时去其他章。背包、机关状态和通关记录会自动保存。']]}};
 const p=pages[page]||pages.overview;modal(`<span class="eyebrow">${first?'新朋友的第一张地图':'随时可打开的玩法说明'}</span><h2 id="dialogTitle">${esc(p.title)}</h2><p>${esc(p.intro)}</p><div class="guide-tabs">${[['overview','先看这里'],['study','学习章怎么玩'],['seaside','海边怎么玩'],['winter','圣诞怎么玩']].map(([key,name])=>`<button data-guide-page="${key}" class="${key===page?'active':''}">${name}</button>`).join('')}</div><div class="guide-step-grid">${p.steps.map(([title,body],i)=>`<div><span class="guide-step-number">${i+1}</span><h3>${title}</h3><p>${body}</p></div>`).join('')}</div><p class="guide-save-note">进度保存在当前浏览器里；更换浏览器或清除网站数据后，不会自动带过来。</p>${guideActions()}<div class="actions"><button id="guideDismiss">明白了，继续探索</button></div>`,true);
 document.querySelectorAll('[data-guide-page]').forEach(el=>el.onclick=()=>showGameGuide(first,el.dataset.guidePage));$('guideChoose').onclick=()=>{finishWelcome();if(activeAwayScene)closeAwayScene();showChapterMap();};$('guideStudy').onclick=()=>{finishWelcome();if(activeAwayScene)closeAwayScene();if(!currentCourse()){close();toast('请先在“我的材料”中选择内置课程或导入课程。');return;}beginStudyWalk();};$('guideBeach').onclick=()=>{finishWelcome();openAwayScene('seaside');};$('guideDismiss').onclick=()=>{finishWelcome();close();};
}
function beginStudyWalk(){const g=guideState();g.walk={chapter:studyState().chapter,section:studySection().id};if(!g.studySeen.includes(g.walk.chapter))g.studySeen.push(g.walk.chapter);close();render();save();guidePoint();}
function guidePoint(){const s=studyState(),sec=studySection(),id=sec.lessons.findIndex(l=>!s.read.includes(l.id));if(id>=0){const p=lessonPosition(id);pointXY(p.x,p.y);toast('先点亮圈附近的物件，试试拼装、观察或展开它。');}else openStudyBasket();}
function renderGameCoach(){let el=$('gameCoach');const g=guideState();if(!g.walk||!currentCourse()||g.walk.chapter!==studyState().chapter||activeAwayScene){el?.remove();return;}const s=studyState(),sec=studySection(),done=s.sealed.includes(g.walk.section),count=sec.lessons.filter(l=>s.deposited.includes(l.id)).length,carried=sec.lessons.some(l=>s.carried.includes(l.id)),all=count===sec.lessons.length;
 let title,body,action;if(done){title='你已经完成第一小节了';body='接下来继续整理其他小节；整章收齐后，到知识素材箱交付，才会开启答题。';action='打开知识素材箱';}else if(basicsReady()){title='基础已经交付，可以开始练习';body='选择答题、复习或错题；随时回知识素材箱查看之前的解释。';action='查看玩法说明';}else if(carried){title='下一步：把素材放进装置';body='点背包中的素材，再点“'+studyTheme().container+'”；也可以直接拖入。';action='打开本节装置';}else if(all){title='本节齐了，记得收好';body='打开“'+studyTheme().container+'”，按本节情境完成操作与判断，再收好成果。';action='完成本节整理';}else{title='下一步：点开物件读一读';body='阅读知识种子，或到场景里收集部件、组装知识物件。进度 '+count+'/'+sec.lessons.length+'，不用急着答题。';action='带我找一份素材';}
 if(!el){el=document.createElement('aside');el.id='gameCoach';el.className='game-coach';document.body.appendChild(el);}el.innerHTML=`<button id="endGameCoach" aria-label="结束新手引导">×</button><span class="eyebrow">陪你玩第一小节</span><strong>${esc(title)}</strong><p>${esc(body)}</p><button id="gameCoachAction">${esc(action)}</button>`;$('endGameCoach').onclick=()=>{g.walk=null;el.remove();save();};$('gameCoachAction').onclick=done?showKnowledgeChest:basicsReady()?()=>showGameGuide(false,'study'):carried||all?openStudyBasket:guidePoint;
}
function showStudyBrief(){const g=guideState(),ch=studyChapter();modal(`<span class="eyebrow">独立学习冒险 · 第 ${studyState().chapter+1} 章</span><h2 id="dialogTitle">${esc(ch.title)}</h2><p>本章有 ${ch.sections.length} 个小节。先收集并阅读基础知识，再整理进每节装置；全章交付后开启练习。</p><div class="guide-mini-route"><span>阅读素材</span> → <span>整理小节</span> → <span>交付本章</span> → <span>练习与复习</span></div><p class="muted">其他章节随时可以进入；本章内部按小节顺序推进，90%测验成绩标记本章通关。</p><div class="actions"><button id="briefStart" class="primary">开始本章</button><button id="briefWalk">带我走第一步</button><button id="briefHelp">完整玩法</button></div>`);const remember=()=>{if(!g.studySeen.includes(studyState().chapter))g.studySeen.push(studyState().chapter);save();};$('briefStart').onclick=()=>{remember();close();};$('briefWalk').onclick=()=>{remember();beginStudyWalk();};$('briefHelp').onclick=()=>{remember();showGameGuide(false,'study');};}
function showAdventureBrief(id,force=false){const g=guideState();if(!force&&g.awaySeen.includes(id))return;const scene=AwayScenes.find(x=>x.id===id);let box=$('adventureBrief');box?.remove();box=document.createElement('aside');box.id='adventureBrief';box.className='adventure-brief';box.innerHTML=`<span class="eyebrow">${esc(scene.tag)} · 入章指南</span><h3>这次冒险，要做三件事。</h3><ol>${scene.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>先点击物件收进随身小包，再拖到对应装置；也可以先点包里的物件、再点目的地。每完成一步，下一步自动出现。</p><small>不会出课程题目 · 进度自动保存 · 可以随时换章</small><div class="actions"><button id="adventureBegin" class="primary">开始这段冒险</button><button id="adventureDetails">看详细操作</button></div>`;$('awayScene').appendChild(box);$('adventureBegin').onclick=()=>{if(!g.awaySeen.includes(id))g.awaySeen.push(id);box.remove();save();};$('adventureDetails').onclick=()=>{if(!g.awaySeen.includes(id))g.awaySeen.push(id);box.remove();save();showGameGuide(false,id);};}
const guideAway=openAwayScene;
openAwayScene=function(id,message=''){guideAway(id,message);if(!activeAwayScene)return;let button=$('awayHow');if(!button){button=document.createElement('button');button.id='awayHow';button.textContent='怎么玩';document.querySelectorAll('.away-switches')[0]?.appendChild(button);}if(button)button.onclick=()=>showAdventureBrief(id,true);renderGameCoach();showAdventureBrief(id);};
const guideEnter=enterStudyChapter;
enterStudyChapter=function(index){guideEnter(index);if(currentCourse()&&!guideState().studySeen.includes(index))showStudyBrief();renderGameCoach();};
const guideHUD=renderHUD;
renderHUD=function(){guideHUD();renderGameCoach();};
help=function(){showGameGuide();};startGuide=function(){if(currentCourse())beginStudyWalk();else showGameGuide();};$('help').textContent='玩法指南';$('help').onclick=help;$('help').ariaLabel='查看玩法指南与新手引导';
const guideInit=initExamWorld;
initExamWorld=function(){guideInit();if(!guideState().welcome)showGameGuide(true);renderGameCoach();};
